// W_Batch_Start — Prep Signature. Same Slack request authentication as W_Abort, but for a
// SLASH COMMAND POST (/dub-batch) instead of an interactivity payload. Slack signs every request:
//   signature = 'v0=' + HMAC_SHA256(signing_secret, `v0:{ts}:{raw_body}`)
// so we must hash the EXACT raw body bytes — the webhook has Raw Body = ON (body arrives binary).
// Slash-command bodies are plain form-urlencoded fields (token, command, text, user_name,
// response_url, ...) — there is no `payload` JSON wrapper as in interactivity.
const cfg = {};
$('Read Config').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });
const secret = (cfg.slack_signing_secret || '').toString();

const wh = $('Slash Command Webhook').first() || {};
const headers = (wh.json && wh.json.headers) || {};
const given_sig = (headers['x-slack-signature'] || headers['X-Slack-Signature'] || '').toString();
const ts = (headers['x-slack-request-timestamp'] || headers['X-Slack-Request-Timestamp'] || '').toString();

let raw = '';
const b = wh.binary;
if (b && b.data && b.data.data) {
  raw = Buffer.from(b.data.data, 'base64').toString('utf8');
} else if (typeof (wh.json && wh.json.body) === 'string') {
  raw = wh.json.body;
}

// Hand-parse a couple form fields for logging (URLSearchParams is unreliable in the sandbox).
const field = (name) => {
  const m = raw.match(new RegExp('(?:^|&)' + name + '=([^&]*)'));
  if (!m) return '';
  try { return decodeURIComponent(m[1].replace(/\+/g, ' ')); } catch (e) { return m[1]; }
};

return [{ json: { base: `v0:${ts}:${raw}`, secret, given_sig, ts, command: field('command'), slack_user: field('user_name') } }];

// W_Batch_Start — Verify the Slack slash-command signature, then allow the batch to start.
// Security gate for the otherwise-public POST webhook: anything that fails verification returns []
// (the batch is NOT fired). Mirrors W_Abort's Verify & Parse Action — same HMAC compare + 5-min
// replay guard. Only a genuine, fresh, correctly-signed /dub-batch gets through.
const prep = $('Prep Signature').first().json || {};
const computed = ($json.computed_sig || '').toString();
const given = (prep.given_sig || '').toString();
const tsNum = Number(prep.ts);
const now = Math.floor(Date.now() / 1000);

if (!prep.secret) { console.warn('W_Batch_Start: slack_signing_secret missing from config — rejecting'); return []; }
if (!given || !computed) { console.warn('W_Batch_Start: missing signature/hash — rejecting'); return []; }
if (!tsNum || Math.abs(now - tsNum) > 300) { console.warn('W_Batch_Start: stale or invalid timestamp — rejecting (replay guard)'); return []; }

const expected = 'v0=' + computed;
if (expected.length !== given.length || expected !== given) { console.warn('W_Batch_Start: Slack signature mismatch — rejecting'); return []; }

console.log(`W_Batch_Start: verified /dub-batch from ${prep.slack_user || 'unknown'}`);
return [{ json: { ok: true, slack_user: prep.slack_user, command: prep.command } }];
